import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';
import 'package:provider/provider.dart';

import '../state.dart';
import '../theme.dart';
import '../widgets/glass.dart';
import 'report_screen.dart';

// ─── Data-source note (Task 5-a) ────────────────────────────────────────────
// ALL safety overlay data currently comes from ONE source:
//   • Synthetic / seed data generated by backend/app/seed.py at startup.
//     - Segment geometry, signal levels, isolation scores: hardcoded constants.
//     - One demo "poor_lighting" report on segment B2: hardcoded in seed_demo().
//     - Signal samples: 3 synthetic samples per segment labelled carrier="demo".
//   • User-submitted reports (after the demo): stored in SQLite via POST /reports,
//     counted only after de-duplication and presence check; turned red only after
//     ≥3 distinct users + moderator confirmation.
//   • No external feeds (no Reddit, news, police APIs, etc.) are connected.
// ────────────────────────────────────────────────────────────────────────────

// Filter state
class _MapFilter {
  String? category; // null = all
  String timeRange;  // 'all' | '24h' | '7d'
  String minConf;    // 'all' | 'low' | 'medium' | 'high'
  _MapFilter({this.category, this.timeRange = 'all', this.minConf = 'all'});
  _MapFilter copyWith({String? category, bool clearCat = false, String? timeRange, String? minConf}) => _MapFilter(
    category: clearCat ? null : (category ?? this.category),
    timeRange: timeRange ?? this.timeRange,
    minConf: minConf ?? this.minConf,
  );
}

class MapScreen extends StatefulWidget {
  const MapScreen({super.key});
  @override
  State<MapScreen> createState() => _MapScreenState();
}

class _MapScreenState extends State<MapScreen> {
  _MapFilter _filter = _MapFilter();
  Map<String, dynamic>? _detail; // segment detail card

  List<Polyline> _lines(AppState s, List<Map<String, dynamic>> segs) {
    final out = <Polyline>[];
    List<LatLng> pts(Map<String, dynamic> seg) =>
        [for (final p in seg['geom'] as List) LatLng((p[0] as num).toDouble(), (p[1] as num).toDouble())];

    if (s.showSignal) {
      for (final seg in segs) {
        switch (seg['signal']) {
          case 'weak':
            out.add(Polyline(points: pts(seg), strokeWidth: 14, color: C.navy.withValues(alpha: 0.30)));
          case 'none':
            out.add(Polyline(points: pts(seg), strokeWidth: 14, color: C.navy.withValues(alpha: 0.55)));
          case null:
            out.add(Polyline(points: pts(seg), strokeWidth: 3, color: const Color(0x99000000), pattern: const StrokePattern.dotted()));
        }
      }
    }

    if (s.showConcern) {
      for (final seg in segs) {
        final concern = seg['concern'] as String?;
        if (concern == 'amber') out.add(Polyline(points: pts(seg), strokeWidth: 6, color: C.amber));
        if (concern == 'red') out.add(Polyline(points: pts(seg), strokeWidth: 6, color: C.red));
      }
    }

    final sel = s.selectedRoute;
    if (sel != null && sel['coords'] is List) {
      final rawCoords = sel['coords'] as List;
      final routePts = [for (final p in rawCoords) LatLng((p[0] as num).toDouble(), (p[1] as num).toDouble())];
      if (routePts.length >= 2) {
        out.add(Polyline(points: routePts, strokeWidth: 10, color: Colors.white.withValues(alpha: 0.85)));
        out.add(Polyline(points: routePts, strokeWidth: 6, color: C.accent));
      }
    }

    return out;
  }

  /// Concern markers — one per flagged segment, tappable, with provenance card.
  List<Marker> _concernMarkers(List<Map<String, dynamic>> segs) {
    final out = <Marker>[];
    for (final seg in segs) {
      final concern = seg['concern'] as String?;
      if (concern == null || concern == 'no_data') continue;
      final geom = seg['geom'] as List;
      if (geom.isEmpty) continue;
      final midIdx = geom.length ~/ 2;
      final pt = LatLng((geom[midIdx][0] as num).toDouble(), (geom[midIdx][1] as num).toDouble());
      final color = concern == 'red' ? C.red : C.amber;
      out.add(Marker(
        point: pt,
        width: 36,
        height: 36,
        child: GestureDetector(
          onTap: () => setState(() => _detail = seg),
          child: Container(
            decoration: BoxDecoration(color: color, shape: BoxShape.circle, border: Border.all(color: Colors.white, width: 2),
                boxShadow: [BoxShadow(color: color.withValues(alpha: 0.4), blurRadius: 6)]),
            child: Icon(concern == 'red' ? Icons.warning_rounded : Icons.info_outline, color: Colors.white, size: 18),
          ),
        ),
      ));
    }
    return out;
  }

  /// Filter the segment list by the active filter settings.
  List<Map<String, dynamic>> _applyFilter(List<Map<String, dynamic>> segs) {
    return segs.where((seg) {
      if (_filter.category != null && seg['concern'] != _filter.category) return false;
      // Confidence filter: 'low' = no_data/unverified, 'medium' = amber, 'high' = red+reviewed
      if (_filter.minConf == 'medium') {
        if (seg['concern'] == null || seg['concern'] == 'no_data') return false;
      } else if (_filter.minConf == 'high') {
        if (seg['concern'] != 'red') return false;
      }
      return true;
    }).toList();
  }

  @override
  Widget build(BuildContext context) {
    final s = context.watch<AppState>();
    final filteredSegs = _applyFilter(s.segments);
    final sel = s.selectedRoute;
    List<LatLng>? routePts;
    if (sel != null && sel['coords'] is List) {
      final rawCoords = sel['coords'] as List;
      routePts = [for (final p in rawCoords) LatLng((p[0] as num).toDouble(), (p[1] as num).toDouble())];
    }

    return Stack(children: [
      FlutterMap(
        mapController: s.mapController,
        options: MapOptions(
          initialCenter: regionCenter,
          initialZoom: 10,
          minZoom: 7,
          maxZoom: 18,
          cameraConstraint: CameraConstraint.containCenter(bounds: regionBounds),
          onTap: (_, p) { s.setPin(p); setState(() => _detail = null); },
        ),
        children: [
          TileLayer(urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png', userAgentPackageName: 'in.safecircle.app'),
          PolylineLayer(polylines: _lines(s, filteredSegs)),
          MarkerLayer(markers: [
            ..._concernMarkers(filteredSegs),
            if (s.me != null)
              Marker(
                point: s.me!,
                width: 24,
                height: 24,
                child: Container(decoration: BoxDecoration(color: C.accent, shape: BoxShape.circle, border: Border.all(color: Colors.white, width: 3))),
              ),
            if (routePts != null && routePts.isNotEmpty) ...[
              Marker(point: routePts.first, width: 28, height: 28,
                  child: Container(decoration: BoxDecoration(color: const Color(0xFF1B8A44), shape: BoxShape.circle, border: Border.all(color: Colors.white, width: 2)),
                      child: const Icon(Icons.trip_origin, color: Colors.white, size: 16))),
              Marker(point: routePts.last, width: 32, height: 32, alignment: Alignment.topCenter,
                  child: const Icon(Icons.flag_rounded, color: C.accent, size: 30)),
            ],
            if (s.pin != null)
              Marker(point: s.pin!, width: 44, height: 44, alignment: Alignment.topCenter,
                  child: const Icon(Icons.location_on, color: C.red, size: 44)),
          ]),
          const RichAttributionWidget(attributions: [TextSourceAttribution('OpenStreetMap contributors')]),
        ],
      ),

      // ── Top HUD ──
      SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            if (s.isOffline)
              Container(
                margin: const EdgeInsets.only(bottom: 8),
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                decoration: BoxDecoration(color: C.amber.withValues(alpha: 0.95), borderRadius: BorderRadius.circular(16)),
                child: const Row(mainAxisSize: MainAxisSize.min, children: [
                  Icon(Icons.wifi_off, size: 16, color: Colors.white),
                  SizedBox(width: 8),
                  Text('Offline — showing cached map snapshot', style: TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.w700)),
                ]),
              ),
            // Search bar
            Glass(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
              child: InkWell(
                onTap: () => s.setTab(1),
                child: Row(children: [
                  const Icon(Icons.search, color: C.body),
                  const SizedBox(width: 12),
                  Expanded(child: Text(
                    s.language == 'en' ? 'Where to?  Compare routes' : 'कहाँ जाना है? मार्ग तुलना करें',
                    style: const TextStyle(color: C.body, fontSize: 16),
                  )),
                  InkWell(
                    onTap: s.toggleLanguage,
                    borderRadius: BorderRadius.circular(12),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(color: C.glass, borderRadius: BorderRadius.circular(12), border: Border.all(color: C.glassBorder)),
                      child: Text(s.language == 'en' ? 'हिन्दी' : 'EN', style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w800, color: C.ink)),
                    ),
                  ),
                ]),
              ),
            ),
            const SizedBox(height: 10),
            // Layer toggles
            Wrap(spacing: 8, runSpacing: 6, children: [
              Pill(s.language == 'en' ? 'Concerns' : 'सुरक्षा समस्याएं', selected: s.showConcern, onTap: s.toggleConcern, dot: C.amber),
              Pill(s.language == 'en' ? 'Weak signal' : 'कमज़ोर सिग्नल', selected: s.showSignal, onTap: s.toggleSignal, dot: C.navy),
              Pill('Demo: Pin A3', selected: false, onTap: s.setDemoA3Pin, dot: C.red),
            ]),
            const SizedBox(height: 8),
            // Filter row
            SizedBox(height: 44, child: ListView(scrollDirection: Axis.horizontal, children: [
              _FilterChip(
                label: _filter.minConf == 'all' ? 'All confidence' : _filter.minConf == 'medium' ? 'Med+ confidence' : 'High confidence',
                onTap: () => _cycleConf(),
              ),
              const SizedBox(width: 6),
              _FilterChip(
                label: 'My location',
                icon: Icons.my_location,
                onTap: () async {
                  final loc = await s.locate();
                  if (loc != null) s.mapController.move(loc, 15);
                },
              ),
              const SizedBox(width: 6),
              _FilterChip(label: 'Legend', icon: Icons.info_outline, onTap: () => _showLegend(context)),
            ])),
            const SizedBox(height: 8),
            // City pills
            SizedBox(height: 48, child: ListView(scrollDirection: Axis.horizontal, children: [
              for (final p in s.places) Padding(padding: const EdgeInsets.only(right: 8), child: Pill(p.name, selected: false, onTap: () => s.jumpTo(p))),
            ])),
            if (s.error != null)
              Padding(padding: const EdgeInsets.only(top: 12),
                  child: Glass(child: Text(s.error!, style: const TextStyle(color: C.red, fontWeight: FontWeight.w600)))),
          ]),
        ),
      ),

      // ── Segment detail card ──
      if (_detail != null)
        Positioned(
          left: 16, right: 16, bottom: 110,
          child: _SegmentCard(seg: _detail!, onClose: () => setState(() => _detail = null)),
        )
      else
        // ── Bottom mode card (default) ──
        Align(
          alignment: Alignment.bottomCenter,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 104),
            child: Glass(
              child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
                if (sel != null) ...[
                  InkWell(
                    onTap: () => s.setTab(1),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                      margin: const EdgeInsets.only(bottom: 8),
                      decoration: BoxDecoration(color: C.accent.withValues(alpha: 0.12), borderRadius: BorderRadius.circular(12), border: Border.all(color: C.accent.withValues(alpha: 0.3))),
                      child: Row(children: [
                        const Icon(Icons.navigation, color: C.accent, size: 16),
                        const SizedBox(width: 8),
                        Expanded(child: Text('Active route: ${sel['name']} (${(sel['minutes'] as num).round()} min, ${(sel['km'] as num).toStringAsFixed(1)} km)',
                            style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: C.ink))),
                        const Text('Change', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: C.accent)),
                      ]),
                    ),
                  ),
                ],
                Row(children: [
                  Expanded(child: Text(s.language == 'en' ? 'Night Safety Mode' : 'नाइट सेफ्टी मोड',
                      style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w800))),
                  Switch(value: s.mode == 'night', onChanged: (v) => s.setMode(v ? 'night' : 'day')),
                ]),
                const Text('Wide blue = weak signal. Dotted grey = not measured. No colour on a road means no data, never safe.', style: hSmall),
                const SizedBox(height: 12),
                PrimaryButton(
                  s.pin == null
                      ? (s.language == 'en' ? 'Tap the map, then report a concern' : 'मानचित्र छुएं, फिर चिंता दर्ज करें')
                      : (s.language == 'en' ? 'Report a concern here' : 'यहाँ समस्या रिपोर्ट करें'),
                  onPressed: s.pin == null ? null : () => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const ReportScreen())),
                ),
              ]),
            ),
          ),
        ),
    ]);
  }

  void _cycleConf() {
    final order = ['all', 'medium', 'high'];
    final next = order[(order.indexOf(_filter.minConf) + 1) % order.length];
    setState(() => _filter = _filter.copyWith(minConf: next));
  }

  void _showLegend(BuildContext context) {
    showModalBottomSheet(
      context: context,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => Padding(
        padding: const EdgeInsets.all(24),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Map legend', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w800)),
          const SizedBox(height: 16),
          const _LegendRow(color: C.amber, label: 'Amber — community concern (not yet reviewed)'),
          const _LegendRow(color: C.red, label: 'Red — confirmed by moderator after ≥3 reports'),
          _LegendRow(color: C.navy.withValues(alpha: 0.5), label: 'Blue band — weak or no mobile signal'),
          const _LegendRow(color: Color(0x66000000), label: 'Dotted grey — signal not measured (unknown)'),
          const SizedBox(height: 12),
          // Data provenance notice
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(color: C.amber.withValues(alpha: 0.08), borderRadius: BorderRadius.circular(12), border: Border.all(color: C.amber.withValues(alpha: 0.3))),
            child: const Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Icon(Icons.science_outlined, size: 16, color: C.amber),
              SizedBox(width: 8),
              Expanded(child: Text(
                'DEMO DATA — All overlays are currently synthetic data generated at startup for illustration. '
                'No external data feeds (news, police, social media) are connected. '
                'Real data will come from verified user reports + moderator review.',
                style: TextStyle(fontSize: 12, color: C.body),
              )),
            ]),
          ),
        ]),
      ),
    );
  }
}

// ── Filter chip ──────────────────────────────────────────────────────────────
class _FilterChip extends StatelessWidget {
  const _FilterChip({required this.label, this.icon, required this.onTap});
  final String label;
  final IconData? icon;
  final VoidCallback onTap;
  @override
  Widget build(BuildContext context) => GestureDetector(
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
          decoration: BoxDecoration(color: C.glass, borderRadius: BorderRadius.circular(22), border: Border.all(color: C.glassBorder)),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            if (icon != null) ...[Icon(icon, size: 15, color: C.ink), const SizedBox(width: 6)],
            Text(label, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: C.ink)),
          ]),
        ),
      );
}

// ── Segment provenance detail card ───────────────────────────────────────────
class _SegmentCard extends StatelessWidget {
  const _SegmentCard({required this.seg, required this.onClose});
  final Map<String, dynamic> seg;
  final VoidCallback onClose;

  String _confidence(Map<String, dynamic> seg) {
    final concern = seg['concern'] as String?;
    if (concern == 'red') return 'High — moderator confirmed';
    if (concern == 'amber') return 'Medium — community reports, unreviewed';
    return 'Low — no reports or not measured';
  }

  Color _confColor(Map<String, dynamic> seg) {
    final concern = seg['concern'] as String?;
    if (concern == 'red') return C.red;
    if (concern == 'amber') return C.amber;
    return C.body;
  }

  @override
  Widget build(BuildContext context) {
    final id = seg['id'] as String? ?? '—';
    final name = seg['name'] as String? ?? id;
    final concern = seg['concern'] as String? ?? 'no_data';
    final signal = seg['signal'] as String?;
    final reportCount = seg['report_count'] as int? ?? 0;
    final lastReport = seg['last_report_at'] as String?;
    return Glass(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Expanded(child: Text(name, style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15))),
          GestureDetector(onTap: onClose, child: const Icon(Icons.close, size: 20, color: C.body)),
        ]),
        const SizedBox(height: 10),
        _dataRow('Concern', concern == 'no_data' ? 'None recorded' : concern, _confColor(seg)),
        _dataRow('Signal', signal ?? 'Not measured', C.body),
        _dataRow('Reports', '$reportCount user report${reportCount == 1 ? '' : 's'}', C.body),
        _dataRow('Last report', lastReport != null ? _fmt(lastReport) : 'Never', C.body),
        _dataRow('Confidence', _confidence(seg), _confColor(seg)),
        const SizedBox(height: 8),
        // Data source provenance
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
          decoration: BoxDecoration(color: C.amber.withValues(alpha: 0.09), borderRadius: BorderRadius.circular(10)),
          child: const Row(children: [
            Icon(Icons.science_outlined, size: 13, color: C.amber),
            SizedBox(width: 6),
            Text('Demo / synthetic data', style: TextStyle(fontSize: 11, color: C.amber, fontWeight: FontWeight.w700)),
          ]),
        ),
      ]),
    );
  }

  String _fmt(String iso) {
    try {
      final d = DateTime.parse(iso).toLocal();
      return '${d.day}/${d.month}/${d.year} ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
    } catch (_) {
      return iso;
    }
  }

  Widget _dataRow(String k, String v, Color vc) => Padding(
        padding: const EdgeInsets.only(bottom: 4),
        child: Row(children: [
          Text('$k: ', style: const TextStyle(fontSize: 13, color: C.body)),
          Text(v, style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: vc)),
        ]),
      );
}

// ── Legend row ───────────────────────────────────────────────────────────────
class _LegendRow extends StatelessWidget {
  const _LegendRow({required this.color, required this.label});
  final Color color;
  final String label;
  @override
  Widget build(BuildContext context) => Padding(
        padding: const EdgeInsets.only(bottom: 10),
        child: Row(children: [
          Container(width: 32, height: 8, decoration: BoxDecoration(color: color, borderRadius: BorderRadius.circular(4))),
          const SizedBox(width: 12),
          Expanded(child: Text(label, style: const TextStyle(fontSize: 13))),
        ]),
      );
}
